const urls = new Map<PhotoId, string>();

/** A photo as an image's source: its SVG in a data URI, made once. */
export function photoDataUrl(id: PhotoId): string {
  let url = urls.get(id);
  if (url === undefined) urls.set(id, (url = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(PHOTOS[id])}`));
  return url;
}
